/** Public application origin used for auth links generated by server actions. */
export function getSiteOrigin(env: Record<string, string | undefined> = process.env): string {
  const configured = env.NEXT_PUBLIC_SITE_URL?.trim();
  const vercelHost = env.VERCEL_URL?.trim();
  const usePreviewHost = env.VERCEL_ENV === "preview" && vercelHost;
  const candidate = usePreviewHost
    ? `https://${vercelHost}`
    : configured || (vercelHost ? `https://${vercelHost}` : "http://localhost:3000");

  let url: URL;
  try {
    url = new URL(candidate);
  } catch {
    throw new Error("NEXT_PUBLIC_SITE_URL must be a valid absolute URL.");
  }

  if (!["https:", "http:"].includes(url.protocol) || url.username || url.password) {
    throw new Error("NEXT_PUBLIC_SITE_URL must use HTTP(S) and cannot contain credentials.");
  }
  if (url.protocol === "http:" && url.hostname !== "localhost" && url.hostname !== "127.0.0.1") {
    throw new Error("Public application URLs must use HTTPS outside localhost.");
  }
  if (env.VERCEL_ENV === "production" && ["localhost", "127.0.0.1"].includes(url.hostname)) {
    throw new Error("Production auth links cannot point to localhost.");
  }
  return url.origin;
}
